 void SelectManiaMode(int mode){app.Games.OsuMania.Mode=mode;app.Save();app.Pet.SetGameCorner();app.Pet.Render();Rebuild();}
 void BeginBinding(){if(page!="game-osu")return;captureKeys=new int[app.Games.OsuMania.Mode];captureIndex=0;binding=true;UpdateGameTiles();}
 void UpdateGameTiles(){if(gameTiles==null)return;var values=binding?captureKeys:app.Games.OsuMania.CurrentKeys;for(int i=0;i<gameTiles.Length;i++){gameTiles[i].Text=values[i]==0?"":ManiaKeys.Label(values[i]);gameTiles[i].Primary=binding&&i==captureIndex;gameTiles[i].Invalidate();}if(binding)gameBindingStatus.Text="请按第 "+(captureIndex+1)+" 个键（"+captureKeys.Length+"K），从左向右录入。";else if(string.IsNullOrEmpty(gameBindingStatus.Text))gameBindingStatus.Text="点击“重置键绑定”开始录入；4K～8K 分别保存。";}
 void CaptureGameKey(Keys raw){if(!binding)return;if(!ManiaKeys.Bindable(raw)){gameBindingStatus.Text="请按一个普通键，不要按 Esc、组合键或鼠标键。";return;}int code=(int)(raw&Keys.KeyCode);for(int i=0;i<captureIndex;i++)if(captureKeys[i]==code){gameBindingStatus.Text=ManiaKeys.Label(code)+" 已在本轮第 "+(i+1)+" 个位置使用，请换一个键。";return;}captureKeys[captureIndex]=code;captureIndex++;if(captureIndex<captureKeys.Length){UpdateGameTiles();return;}try{app.Games.OsuMania.SetKeys(app.Games.OsuMania.Mode,captureKeys);app.Save();app.Pet.SetGameCorner();binding=false;captureKeys=null;gameBindingStatus.Text="按键已保存。";UpdateGameTiles();app.Pet.Render();}catch(ArgumentException e){gameBindingStatus.Text=e.Message;}}
 // Route command and ordinary keys through one consuming path. Bit 30 marks
 // auto-repeat, which must not fill another slot or produce a duplicate warning.
 [DllImport("user32.dll")]static extern uint MapVirtualKey(uint code,uint mapType);
 bool CaptureGameMessage(ref Message msg,Keys keyData){if(!binding)return false;if(msg.Msg==0x100||msg.Msg==0x104){if((msg.LParam.ToInt64()&(1L<<30))==0){if((keyData&Keys.KeyCode)==Keys.ProcessKey){uint scan=(uint)((msg.LParam.ToInt64()>>16)&0xff);if((msg.LParam.ToInt64()&(1L<<24))!=0)scan|=0xe000;keyData=(keyData&Keys.Modifiers)|(Keys)MapVirtualKey(scan,3);}CaptureGameKey(keyData);}return true;}return msg.Msg==0x101||msg.Msg==0x105||msg.Msg==0x102||msg.Msg==0x106;}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){return CaptureVocabularyKey(keyData)||CaptureGameMessage(ref msg,keyData)||base.ProcessCmdKey(ref msg,keyData);}
 protected override bool ProcessKeyPreview(ref Message msg){return CaptureGameMessage(ref msg,(Keys)msg.WParam.ToInt32()|ModifierKeys)||base.ProcessKeyPreview(ref msg);}
